    const [rows, bandwidthRows] = await Promise.all([
      repository.accountResourceUsage.listCurrentStorage(ownerId),
      repository.accountResourceUsage.listBandwidthHistory(
        ownerId,
        period.start,
        period.end,
        "day",
      ),
    ]);
    return reply
