  app.get<{
    Params: { workerId: string };
    Querystring: { afterCursor?: string; minimumLevel?: string };
  }>(
    "/api/workers/:workerId/logs/stream",
    { websocket: true },
    async (socket, request) => {
      const origin = request.headers.origin;
      if (!origin || !config.appOrigins.includes(origin)) {
        socket.close(1008, "Origin is not allowed");
        return;
      }
      if (request.principal.state !== "authenticated") {
        socket.close(1008, "Authentication is required");
        return;
      }
      if (!registerAuthenticatedSocket(socket, request)) return;
      registerSessionSocket(socket, request);
      const query = workerLogReadQuerySchema.safeParse({
        afterCursor: request.query.afterCursor,
        minimumLevel: request.query.minimumLevel,
      });
      if (!query.success) {
        socket.close(1008, "Invalid worker log stream request");
        return;
      }
      const principal = authenticatedPrincipal(request);
      const workerId = request.params.workerId;
      const worker = await repository.getWorker(principal.user.id, workerId);
      if (!worker) {
        socket.close(1008, "Worker log stream is not authorized");
        return;
      }
      if (!bridge.isConnected(workerId) || !bridge.subscribeNotifications) {
        socket.close(1013, "Worker is offline");
        return;
      }

      const subscriptionId = randomUUID();
      let started = false;
      let closed = false;
      let heartbeatTimer: ReturnType<typeof setInterval> | null = null;
      let renewTimer: ReturnType<typeof setInterval> | null = null;
      let unsubscribeNotifications: (() => void) | null = null;
      let unsubscribeDisconnect: (() => void) | null = null;
      const stopWorkerStream = (): void => {
        if (!started) return;
        started = false;
        void bridge
          .request(
            workerId,
            {
              type: "diagnostics.logs.stream.stop",
              subscriptionId,
            },
            { ownerId: principal.user.id, timeoutMs: 5_000 },
          )
          .catch(() => undefined);
      };
      const cleanup = (): void => {
        if (closed) return;
        closed = true;
        if (heartbeatTimer) clearInterval(heartbeatTimer);
        heartbeatTimer = null;
        if (renewTimer) clearInterval(renewTimer);
        renewTimer = null;
        unsubscribeNotifications?.();
        unsubscribeNotifications = null;
        unsubscribeDisconnect?.();
        unsubscribeDisconnect = null;
        stopWorkerStream();
      };
      const send = (message: unknown): boolean => {
        if (socket.readyState !== 1) return false;
        if (workerLogStreamConsumerIsSlow(socket.bufferedAmount)) {
          socket.close(1013, "Worker log stream consumer is too slow");
          cleanup();
          return false;
        }
        const encoded = JSON.stringify(
          workerLogStreamServerMessageSchema.parse(message),
        );
        socket.send(encoded);
        recordEncodedFrame(accountUsageMeter, {
          ownerId: principal.user.id,
          direction: "egress",
          channel: "worker-log-stream",
          data: encoded,
        });
        return true;
      };
      socket.once("close", cleanup);
      heartbeatTimer = setInterval(() => {
        if (socket.readyState === 1) socket.ping();
      }, WORKER_LOG_STREAM_HEARTBEAT_MS);
      heartbeatTimer.unref();
      unsubscribeDisconnect = bridge.subscribeWorkerDisconnect(workerId, () => {
        send({
          type: "error",
          code: "worker-offline",
          message: "Worker disconnected.",
          retryable: true,
        });
        socket.close(1013, "Worker disconnected");
        cleanup();
      });
      unsubscribeNotifications = bridge.subscribeNotifications(
        workerId,
        (notification) => {
          if (
            notification.type !== "diagnostics.logs.observed" ||
            notification.subscriptionId !== subscriptionId
          ) {
            return;
          }
          send({
            type: "batch",
            records: notification.records,
            nextCursor: notification.nextCursor,
            oldestCursor: notification.oldestCursor,
            latestCursor: notification.latestCursor,
            truncated: notification.truncated,
          });
        },
      );

      try {
        workerLogStreamStartResultSchema.parse(
          await bridge.request(
            workerId,
            {
              type: "diagnostics.logs.stream.start",
              subscriptionId,
              afterCursor: query.data.afterCursor,
              minimumLevel: query.data.minimumLevel,
              leaseMs: WORKER_LOG_STREAM_LEASE_MS,
            },
            { ownerId: principal.user.id, timeoutMs: 5_000 },
          ),
        );
        started = true;
        if (closed) {
          stopWorkerStream();
          return;
        }
        send({
          type: "ready",
          subscriptionId,
          nextCursor: query.data.afterCursor,
        });
        renewTimer = setInterval(() => {
          void bridge
            .request(
              workerId,
              {
                type: "diagnostics.logs.stream.renew",
                subscriptionId,
                leaseMs: WORKER_LOG_STREAM_LEASE_MS,
              },
              { ownerId: principal.user.id, timeoutMs: 5_000 },
            )
            .then((result) => workerLogStreamRenewResultSchema.parse(result))
            .catch(() => {
              if (socket.readyState === 1) {
                socket.close(1013, "Worker log stream lease was lost");
              }
              cleanup();
            });
        }, WORKER_LOG_STREAM_RENEW_MS);
        renewTimer.unref();
      } catch {
        send({
          type: "error",
          code: "stream-unavailable",
          message: "Worker log stream could not start.",
          retryable: true,
        });
        socket.close(1013, "Worker log stream could not start");
        cleanup();
      }
    },
  );

  app.post<{ Params: { workerId: string } }>(
    "/api/workers/:workerId/direct-probe",
    { logLevel: "warn" },
    async (request, reply) => {
      const principal = authenticatedPrincipal(request);
      const authSessionId = principal.sessionId ?? `local:${principal.user.id}`;
      const preparationLease = directAttachments.acquirePreparationLease({
        authSessionId,
        ownerId: principal.user.id,
        resourceId: request.params.workerId,
        resourceKind: "probe",
      });
      if (!preparationLease) {
        return reply.code(409).send({
          error: "The owning resource is being revoked.",
        });
      }
      try {
        const worker = await repository.getWorker(
          principal.user.id,
          request.params.workerId,
        );
        if (!worker) {
          return reply.code(404).send({ error: "Worker not found." });
        }
        const ticket = await directAttachments.prepare({
          authSessionId,
          channels: ["probe"],
          ownerId: principal.user.id,
          preparationLease,
          resourceId: request.params.workerId,
          resourceKind: "probe",
          worker,
        });
        if (!directAttachments.preparationLeaseIsActive(preparationLease)) {
          await directAttachments.revoke(
            ticket.binding.capabilityId,
            "Owning resource was revoked",
          );
          return reply.code(409).send({
            error:
              "The owning resource changed while direct access was opening.",
          });
        }
        return reply.code(201).send(directAttachmentTicketSchema.parse(ticket));
      } catch (error) {
        if (error instanceof DirectAttachmentUnavailableError) {
          return reply.code(409).send({ error: error.message });
        }
        throw error;
      } finally {
        directAttachments.releasePreparationLease(preparationLease);
      }
    },
  );

  app.delete<{ Params: { capabilityId: string } }>(
    "/api/direct-attachments/:capabilityId",
    { logLevel: "warn" },
    async (request, reply) => {
      const principal = authenticatedPrincipal(request);
      await directAttachments.revoke(
        request.params.capabilityId,
        "Client released direct attachment",
        {
          authSessionId: principal.sessionId ?? `local:${principal.user.id}`,
          ownerId: principal.user.id,
        },
      );
      // A completed or concurrent revocation is already the requested end state.
      return reply.code(204).send();
    },
  );

  app.post<{ Params: { capabilityId: string } }>(
    "/api/direct-attachments/:capabilityId/telemetry",
    { logLevel: "warn" },
    async (request, reply) => {
      const principal = authenticatedPrincipal(request);
      const telemetry = directTransportTelemetrySchema.parse(request.body);
      const delta = directAttachments.recordTelemetry(
        request.params.capabilityId,
        {
          authSessionId: principal.sessionId ?? `local:${principal.user.id}`,
          ownerId: principal.user.id,
        },
        telemetry,
      );
      if (!delta) {
        return reply.code(404).send({ error: "Direct attachment not found." });
      }
      if (
        delta.resourceKind === "tunnel" &&
        (delta.bytesFromLocal > 0 ||
          delta.bytesToLocal > 0 ||
          delta.connectionsOpened > 0 ||
          delta.connectionsClosed > 0)
      ) {
        codeTunnel.recordTunnelActivity(delta.resourceId);
      }
      operationalMetrics.recordDirectTransport(delta.resourceKind, delta);
      return reply.code(204).send();
    },
  );

