  app.put<{ Params: { terminalId: string } }>(
    "/api/terminals/:terminalId/service",
    async (request, reply) => {
      const input = encryptedTerminalServiceConfigurationSchema.safeParse(
        request.body,
      );
      if (!input.success) {
        return reply.code(400).send(invalidBody(input.error.issues));
      }
      try {
        const context = await repository.getTerminalExecutionContext(
          applicationOwnerId(),
          request.params.terminalId,
        );
        if (!context) {
          return reply.code(404).send({ error: "Terminal not found." });
        }
        if (context.kind === "run-configuration" || !context.stateProtection) {
          return reply.code(409).send({
            error:
              "Run configuration terminals are read-only and use the managed runtime output API.",
          });
        }
        const terminal = await repository.updateTerminalService(
          applicationOwnerId(),
          request.params.terminalId,
          input.data,
        );
        if (!terminal) {
          return reply.code(404).send({ error: "Terminal not found." });
        }
        let status: "idle" | "offline" | "running" = input.data.enabled
          ? "offline"
          : "idle";
        if (bridge.isConnected(context.workerId)) {
          try {
            await synchronizeTerminalServicesForWorker(context.workerId);
            status = input.data.enabled ? "running" : "idle";
          } catch {
            app.log.warn(
              { terminalId: terminal.id },
              "Terminal service will reconcile when the worker reconnects",
            );
          }
        }
        await updateTerminalStatus(terminal.id, status);
        return reply.send(
          terminalWireSummarySchema.parse({
            ...terminal,
            status,
          }),
        );
      } catch (error) {
        return reply.code(409).send({ error: errorMessage(error) });
      }
    },
  );

  app.post<{ Params: { terminalId: string } }>(
    "/api/terminals/:terminalId/service/restart",
    async (request, reply) => {
      const context = await repository.getTerminalExecutionContext(
        applicationOwnerId(),
        request.params.terminalId,
      );
      if (!context) {
        return reply.code(404).send({ error: "Terminal not found." });
      }
      if (
        await repository.getRunInstanceByTerminal(
          applicationOwnerId(),
          request.params.terminalId,
        )
      ) {
        return reply.code(409).send({
          error: "Run terminals are controlled by their managed Run session.",
        });
      }
      if (!context.serviceEnabled) {
        return reply.code(409).send({ error: "Terminal service is disabled." });
      }
      if (!bridge.isConnected(context.workerId)) {
        await updateTerminalStatus(context.terminalId, "offline");
        return reply.code(503).send({ error: "Project worker is offline." });
      }
      try {
        await bridge.request(
          context.workerId,
          {
            type: "terminal.service.restart",
            terminalId: context.terminalId,
          },
          { timeoutMs: 30_000 },
        );
        await updateTerminalStatus(context.terminalId, "running");
        return reply.code(202).send({ accepted: true });
      } catch (error) {
        return sendWorkerRequestFailure(reply, error);
      }
    },
  );

  app.patch<{ Params: { terminalId: string } }>(
    "/api/terminals/:terminalId/worktree",
    async (request, reply) => {
      const input = worktreeSelectionSchema.safeParse(request.body);
      if (!input.success) {
        return reply.code(400).send(invalidBody(input.error.issues));
      }
      const ownerId = applicationOwnerId();
      try {
        return await directAttachments.mutateResource(
          ownerId,
          "terminal",
          request.params.terminalId,
          async () => {
            const context = await repository.getTerminalExecutionContext(
              ownerId,
              request.params.terminalId,
            );
            if (
              context &&
              (await repository.getRunInstanceByTerminal(
                ownerId,
                request.params.terminalId,
              ))
            ) {
              return reply
                .code(409)
                .send({ error: "Run terminals cannot change worktrees." });
            }
            if (context) await requireProjectWorktrees(context.projectId);
            const terminal = await repository.updateTerminalWorktree(
              ownerId,
              request.params.terminalId,
              input.data,
            );
            return terminal
              ? reply.send(terminalWireSummarySchema.parse(terminal))
              : reply
                  .code(404)
                  .send({ error: "Terminal or worktree not found." });
          },
        );
      } catch (error) {
        return reply.code(409).send({ error: errorMessage(error) });
      }
    },
  );

  app.delete<{ Params: { terminalId: string } }>(
    "/api/terminals/:terminalId",
    async (request, reply) => {
      const ownerId = applicationOwnerId();
      try {
        return await directAttachments.mutateResource(
          ownerId,
          "terminal",
          request.params.terminalId,
          async () => {
            const context = await repository.deleteTerminal(
              ownerId,
              request.params.terminalId,
            );
            if (!context) {
              return reply.code(404).send({ error: "Terminal not found." });
            }
            if (bridge.isConnected(context.workerId)) {
              await bridge
                .request(
                  context.workerId,
                  {
                    type: "terminal.close",
                    terminalId: context.terminalId,
                  },
                  { ownerId, timeoutMs: 5_000 },
                )
                .catch((error: unknown) =>
                  app.log.warn(
                    { err: error, terminalId: context.terminalId },
                    "Could not close deleted terminal",
                  ),
                );
            }
            return reply.code(204).send();
          },
        );
      } catch (error) {
        return reply.code(409).send({ error: errorMessage(error) });
      }
    },
  );

