  app.post<{ Params: { terminalId: string } }>(
    "/api/terminals/:terminalId/direct",
    { logLevel: "warn" },
    async (request, reply) => {
      const input = projectShareDirectCreateSchema.safeParse(request.body);
      if (!input.success) {
        return reply.code(400).send(invalidBody(input.error.issues));
      }
      const principal = authenticatedPrincipal(request);
      const authSessionId = principal.sessionId ?? `local:${principal.user.id}`;
      const preparationLease = directAttachments.acquirePreparationLease({
        authSessionId,
        ownerId: principal.user.id,
        resourceId: request.params.terminalId,
        resourceKind: "terminal",
      });
      if (!preparationLease) {
        return reply.code(409).send({
          error: "The owning resource is being revoked.",
        });
      }
      try {
        const context = await repository.getTerminalExecutionContext(
          principal.user.id,
          request.params.terminalId,
        );
        if (!context) {
          return reply.code(404).send({ error: "Terminal not found." });
        }
        if (context.kind === "run-configuration" || !context.stateProtection) {
          return reply.code(409).send({
            error:
              "Run configuration terminals are read-only and use the managed runtime output API.",
          });
        }
        const assertPreparationActive = () => {
          if (!directAttachments.preparationLeaseIsActive(preparationLease)) {
            throw new DirectAttachmentUnavailableError(
              "The owning resource changed while direct access was opening.",
            );
          }
        };
        assertPreparationActive();
        const worker = await repository.getWorker(
          principal.user.id,
          context.workerId,
        );
        assertPreparationActive();
        if (!worker || !bridge.isConnected(context.workerId)) {
          return reply.code(409).send({ error: "Project worker is offline." });
        }
        const bootstrapAttachmentId = `direct-bootstrap:${randomUUID()}`;
        let startedTerminal = false;
        try {
          const managedRun = await repository.getRunInstanceByTerminal(
            principal.user.id,
            context.terminalId,
          );
          assertPreparationActive();
          let launch: Extract<
            WorkerCommand,
            { type: "terminal.open" }
          >["launch"] = { type: "shell" };
          if (context.linkedChatId) {
            const chat = await repository.getChatExecutionContext(
              principal.user.id,
              context.linkedChatId,
            );
            const runtime = chat ? await runtimeForContext(chat) : null;
            if (!chat || !runtime) {
              return reply.code(409).send({
                error:
                  "Choose a model for this chat before opening its Codex console.",
              });
            }
            launch = {
              type: "codex",
              threadId: chat.threadId,
              model: runtime.model,
              provider: runtime.provider,
              permissionProfileId: effectivePermissionProfile(chat).effectiveId,
              mcpServers: await repository.listEffectiveMcpServers(
                principal.user.id,
                chat.projectId,
                context.workerId,
              ),
            };
            assertPreparationActive();
          }
          let markReady: (() => void) | null = null;
          let markFailed: ((error: Error) => void) | null = null;
          let startupTimer: ReturnType<typeof setTimeout> | null = null;
          const ready = new Promise<void>((resolve, reject) => {
            markReady = resolve;
            markFailed = reject;
            startupTimer = setTimeout(
              () => reject(new Error("Terminal process startup timed out.")),
              15_000,
            );
            startupTimer.unref();
          });
          assertPreparationActive();
          startedTerminal = true;
          const opened = bridge.request(
            context.workerId,
            {
              type: "terminal.open",
              terminalId: context.terminalId,
              managedRunId: managedRun?.id ?? null,
              attachmentId: bootstrapAttachmentId,
              operationId: randomUUID(),
              serverId,
              worktreePath: context.worktreePath,
              stateProtection: context.stateProtection,
              cols: 80,
              rows: 24,
              launch,
            },
            {
              timeoutMs: STREAMING_WORKER_COMMAND_TIMEOUT_MS,
              onEvent: (event) => {
                if (event.type === "terminal.ready") markReady?.();
              },
            },
          );
          void opened
            .then((result) => {
              const parsed = terminalOpenResultSchema.parse(result);
              if (parsed.status === "exited") {
                markFailed?.(
                  new Error("Terminal process exited during startup."),
                );
              }
            })
            .catch((error: unknown) =>
              markFailed?.(
                error instanceof Error
                  ? error
                  : new Error("Terminal process could not start."),
              ),
            );
          await ready.finally(() => {
            if (startupTimer) clearTimeout(startupTimer);
          });
          assertPreparationActive();
          await bridge.request(context.workerId, {
            type: "terminal.detach",
            terminalId: context.terminalId,
            attachmentId: bootstrapAttachmentId,
          });
          assertPreparationActive();
          await updateTerminalStatus(context.terminalId, "running");
          assertPreparationActive();

          const attachmentId = randomUUID();
          const route = {
            tunnelId: `terminal:${context.terminalId}`,
            attachmentId,
            sourceEndpointId: `desktop:${input.data.clientId}:${attachmentId}`,
            destinationEndpointId: `worker:${context.workerId}`,
          };
          const ticket = await directAttachments.prepare({
            attachmentId,
            authSessionId,
            channels: ["tunnel-data"],
            leaseExpiresAt: new Date(Date.now() + 12 * 60 * 60_000),
            ownerId: principal.user.id,
            preparationLease,
            resourceId: context.terminalId,
            resourceKind: "terminal",
            tunnelRoute: {
              ...route,
              target: {
                kind: "adapter",
                adapter: "terminal",
                resourceId: context.terminalId,
                serverId,
                managedRunId: managedRun?.id ?? null,
              },
            },
            worker,
          });
          if (!directAttachments.preparationLeaseIsActive(preparationLease)) {
            await directAttachments.revoke(
              ticket.binding.capabilityId,
              "Owning resource was revoked",
            );
            throw new DirectAttachmentUnavailableError(
              "The owning resource changed while direct access was opening.",
            );
          }
          return reply
            .code(201)
            .send(directTunnelTicketSchema.parse({ ...ticket, route }));
        } catch (error) {
          const revoked =
            !directAttachments.preparationLeaseIsActive(preparationLease);
          if (revoked && startedTerminal) {
            await bridge
              .request(
                context.workerId,
                {
                  type: "terminal.close",
                  terminalId: context.terminalId,
                },
                { ownerId: principal.user.id, timeoutMs: 5_000 },
              )
              .catch(() => undefined);
            await updateTerminalStatus(context.terminalId, "idle").catch(
              () => undefined,
            );
          } else {
            await bridge
              .request(context.workerId, {
                type: "terminal.detach",
                terminalId: context.terminalId,
                attachmentId: bootstrapAttachmentId,
              })
              .catch(() => undefined);
          }
          if (error instanceof DirectAttachmentUnavailableError) {
            return reply.code(409).send({ error: error.message });
          }
          return sendWorkerRequestFailure(reply, error);
        }
      } catch (error) {
        if (error instanceof DirectAttachmentUnavailableError) {
          return reply.code(409).send({ error: error.message });
        }
        throw error;
      } finally {
        directAttachments.releasePreparationLease(preparationLease);
      }
    },
  );

  app.get<{
    Params: { terminalId: string };
    Querystring: { operationId?: string };
  }>(
    "/api/terminals/:terminalId/connect",
    { websocket: true },
    (socket, request) => {
      if (
        !request.headers.origin ||
        !config.appOrigins.includes(request.headers.origin)
      ) {
        socket.close(1008, "Origin not allowed");
        return;
      }
      if (!registerAuthenticatedSocket(socket, request)) return;
      registerSessionSocket(socket, request);
      const operationId = request.query.operationId;
      if (!operationId || operationId.length > 200) {
        socket.close(1008, "Terminal stream operation is required");
        return;
      }
      const ownerId = principalOwnerId(request);
      const attachmentId = randomUUID();
      let terminalId: string | null = null;
      let workerId: string | null = null;
      let closed = false;
      let inputQueue = Promise.resolve();
      const send = (message: unknown) => {
        if (socket.readyState === 1) {
          const encoded = JSON.stringify(
            terminalServerMessageSchema.parse(message),
          );
          socket.send(encoded);
          recordEncodedFrame(accountUsageMeter, {
            ownerId,
            direction: "egress",
            channel: "terminal-relay",
            data: encoded,
          });
        }
      };

      socket.on("close", () => {
        closed = true;
        if (!terminalId || !workerId || !bridge.isConnected(workerId)) return;
        void bridge
          .request(workerId, {
            type: "terminal.detach",
            terminalId,
            attachmentId,
          })
          .catch(() => undefined);
      });

      socket.on("message", (raw) => {
        recordEncodedFrame(accountUsageMeter, {
          ownerId,
          direction: "ingress",
          channel: "terminal-relay",
          data: raw,
        });
        if (!terminalId || !workerId) return;
        let value: unknown;
        try {
          value = JSON.parse(raw.toString());
        } catch {
          send({ type: "error", message: "Invalid terminal message." });
          return;
        }
        const message = terminalClientMessageSchema.safeParse(value);
        if (!message.success) {
          send({ type: "error", message: "Invalid terminal message." });
          return;
        }
        if (
          message.data.type === "input" &&
          message.data.operationId !== operationId
        ) {
          send({ type: "error", message: "Invalid terminal stream." });
          return;
        }
        const command =
          message.data.type === "input"
            ? {
                type: "terminal.input" as const,
                terminalId,
                serverId,
                operationId,
                sequence: message.data.sequence,
                protectedData: message.data.protectedData,
                complete: false,
              }
            : {
                type: "terminal.resize" as const,
                terminalId,
                cols: message.data.cols,
                rows: message.data.rows,
              };
        if (message.data.type === "input") {
          inputQueue = inputQueue
            .then(async () => {
              await bridge.request(workerId!, command, { timeoutMs: 30_000 });
            })
            .catch((error: unknown) => {
              send({ type: "error", message: errorMessage(error) });
            });
        } else {
          void bridge
            .request(workerId, command, { timeoutMs: 30_000 })
            .catch((error: unknown) => {
              send({ type: "error", message: errorMessage(error) });
            });
        }
      });

      void (async () => {
        const context = await repository.getTerminalExecutionContext(
          ownerId,
          request.params.terminalId,
        );
        if (!context) {
          send({ type: "error", message: "Terminal not found." });
          socket.close(1008, "Terminal not found");
          return;
        }
        if (context.kind === "run-configuration" || !context.stateProtection) {
          send({
            type: "error",
            message:
              "Run configuration terminals are read-only and use the managed runtime output API.",
          });
          socket.close(1008, "Run configuration terminal is read-only");
          return;
        }
        if (closed) return;
        terminalId = context.terminalId;
        workerId = context.workerId;
        if (!bridge.isConnected(workerId)) {
          await updateTerminalStatus(terminalId, "offline");
          send({ type: "error", message: "Project worker is offline." });
          socket.close(1013, "Worker offline");
          return;
        }
        if (closed) {
          await updateTerminalStatus(terminalId, "idle");
          return;
        }
        try {
          const managedRun = await repository.getRunInstanceByTerminal(
            ownerId,
            terminalId,
          );
          let launch: Extract<
            WorkerCommand,
            { type: "terminal.open" }
          >["launch"] = { type: "shell" };
          if (context.linkedChatId) {
            const chat = await repository.getChatExecutionContext(
              ownerId,
              context.linkedChatId,
            );
            const runtime = chat ? await runtimeForContext(chat) : null;
            if (!chat || !runtime) {
              throw new Error(
                "Choose a model for this chat before opening its Codex console.",
              );
            }
            launch = {
              type: "codex",
              threadId: chat.threadId,
              model: runtime.model,
              provider: runtime.provider,
              permissionProfileId: effectivePermissionProfile(chat).effectiveId,
              mcpServers: await repository.listEffectiveMcpServers(
                ownerId,
                chat.projectId,
                workerId,
              ),
            };
          }
          const result = terminalOpenResultSchema.parse(
            await bridge.request(
              workerId,
              {
                type: "terminal.open",
                terminalId,
                managedRunId: managedRun?.id ?? null,
                attachmentId,
                operationId,
                serverId,
                worktreePath: context.worktreePath,
                stateProtection: context.stateProtection,
                cols: 80,
                rows: 24,
                launch,
              },
              {
                timeoutMs: STREAMING_WORKER_COMMAND_TIMEOUT_MS,
                onEvent: async (event) => {
                  if (event.type === "terminal.ready") {
                    if (closed) {
                      await bridge.request(workerId!, {
                        type: "terminal.detach",
                        terminalId: terminalId!,
                        attachmentId,
                      });
                      return;
                    }
                    await updateTerminalStatus(terminalId!, "running");
                    send({ type: "ready" });
                  } else if (event.type === "terminal.output") {
                    send(terminalRelayOutputMessage(event));
                  }
                },
              },
            ),
          );
          if (result.status === "exited") {
            await updateTerminalStatus(terminalId, "exited");
            if (!closed) send({ type: "exit", ...result });
          }
        } catch (error) {
          await updateTerminalStatus(
            terminalId,
            error instanceof WorkerUnavailableError ? "offline" : "failed",
          );
          if (!closed) send({ type: "error", message: errorMessage(error) });
        }
      })();
    },
  );

