  app.post<{ Params: { chatId: string } }>(
    "/api/chats/:chatId/fork",
    async (request, reply) => {
      const input = encryptedChatForkSchema.safeParse(request.body ?? {});
      if (!input.success) {
        return reply.code(400).send(invalidBody(input.error.issues));
      }
      const source = await repository.getChatExecutionContext(
        applicationOwnerId(),
        request.params.chatId,
      );
      if (source?.experience === "task") {
        return reply.code(409).send({
          error:
            "Encrypted Task chats must be relocated rather than forked so message row bindings remain valid.",
        });
      }
      if (source && !bridge.isConnected(source.workerId)) {
        return reply.code(503).send({ error: "Project worker is offline." });
      }
      try {
        const chat = await repository.forkChat(
          applicationOwnerId(),
          request.params.chatId,
          input.data,
          async (messages) => {
            const protectedMessages: unknown[] = [];
            for (let offset = 0; offset < messages.length; offset += 100) {
              protectedMessages.push(
                ...chatMessageOpaqueContentListSchema.parse(
                  await bridge.request(source!.workerId, {
                    type: "chat.messages.reprotect",
                    messages: messages
                      .slice(offset, offset + 100)
                      .map((message) => ({
                        source: message,
                        id: randomUUID(),
                        idempotencyKey: `fork:${message.id}`,
                      })),
                  }),
                ),
              );
            }
            return chatMessageOpaqueContentListSchema.parse(protectedMessages);
          },
        );
        return chat
          ? reply.code(201).send(chatWireSummarySchema.parse(chat))
          : reply.code(404).send({ error: "Chat or message not found." });
      } catch (error) {
        if (/unique|duplicate/i.test(errorMessage(error))) {
          return reply.code(409).send({
            error: "This worktree is already leased by another chat.",
          });
        }
        throw error;
      }
    },
  );

  app.post<{ Params: { chatId: string } }>(
    "/api/chats/:chatId/compact",
    async (request, reply) => {
      const context = await repository.getChatExecutionContext(
        applicationOwnerId(),
        request.params.chatId,
      );
      if (!context) {
        return reply.code(404).send({ error: "Chat source not found." });
      }
      if (chatIsExecuting(context.status)) {
        return reply
          .code(409)
          .send({ error: "Wait for the active turn to finish." });
      }
      if (!context.threadId) {
        return reply
          .code(409)
          .send({ error: "Send a message before compacting this chat." });
      }
      if (!bridge.isConnected(context.workerId)) {
        return reply.code(503).send({ error: "Project worker is offline." });
      }
      const runtime = await runtimeForContext(context);
      if (!runtime) {
        return reply.code(400).send({ error: "Selected model was not found." });
      }
      const compactionStartedAtMs = Date.now();
      app.log.info(
        {
          event: "chat.compaction.started",
          subsystem: "chat-execution",
          operation: "compact",
          status: "running",
          chatId: context.chatId,
          projectId: context.projectId,
          workerId: context.workerId,
        },
        "Chat compaction started",
      );
      const result = await bridge.request(context.workerId, {
        type: "chat.compact",
        chatId: context.chatId,
        cwd: context.cwd,
        threadId: context.threadId,
        model: runtime.model,
        provider: runtime.provider,
        permissionProfileId: effectivePermissionProfile(context).effectiveId,
      });
      app.log.info(
        {
          event: "chat.compaction.completed",
          subsystem: "chat-execution",
          operation: "compact",
          status: "completed",
          durationMs: Date.now() - compactionStartedAtMs,
          chatId: context.chatId,
          projectId: context.projectId,
          workerId: context.workerId,
        },
        "Chat compaction completed",
      );
      return reply.send(chatCompactAcceptedSchema.parse(result));
    },
  );

  app.post<{ Params: { chatId: string } }>(
    "/api/chats/:chatId/interrupt",
    async (request, reply) => {
      const context = await repository.getChatExecutionContext(
        applicationOwnerId(),
        request.params.chatId,
      );
      if (!context) {
        return reply.code(404).send({ error: "Chat source not found." });
      }
      const chatCanBeInterrupted =
        context.status === "running" ||
        context.status === "waiting-for-approval";
      if (!chatCanBeInterrupted) {
        return reply.send(
          chatInterruptAcceptedSchema.parse({ interrupted: false }),
        );
      }
      const runtime = await runtimeForContext(context);
      if (!runtime) {
        return reply.code(400).send({ error: "Selected model was not found." });
      }
      const result = await bridge.request(context.workerId, {
        type: "chat.interrupt",
        chatId: context.chatId,
        threadId: context.threadId,
        model: runtime.model,
        provider: runtime.provider,
      });
      const parsedResult = chatInterruptAcceptedSchema.parse(result);
      if (
        parsedResult.interrupted &&
        context.status === "waiting-for-approval"
      ) {
        await interruptLiveAgentInteractionRequests(context.chatId);
      }
      app.log.info(
        {
          event: "chat.interrupt.requested",
          subsystem: "chat-execution",
          operation: "interrupt",
          status: parsedResult.interrupted ? "accepted" : "not-active",
          chatId: context.chatId,
          projectId: context.projectId,
          workerId: context.workerId,
        },
        parsedResult.interrupted
          ? "Agent turn interruption accepted"
          : "Agent turn was not active",
      );
      return reply.send(parsedResult);
    },
  );

  app.patch<{ Params: { chatId: string } }>(
    "/api/chats/:chatId/pause",
    async (request, reply) => {
      const input = chatPauseUpdateSchema.safeParse(request.body);
      if (!input.success) {
        return reply.code(400).send(invalidBody(input.error.issues));
      }
      const context = await repository.getChatExecutionContext(
        applicationOwnerId(),
        request.params.chatId,
      );
      if (!context) {
        return reply.code(404).send({ error: "Chat source not found." });
      }

      if (
        !input.data.paused &&
        !bridge.isConnected(context.workerId) &&
        (context.threadId ||
          (
            await repository.listQueuedPrompts(
              applicationOwnerId(),
              context.chatId,
            )
          ).length > 0)
      ) {
        return reply.code(503).send({
          error:
            "The project worker is offline. This chat remains paused so its next action is not lost.",
        });
      }

      const workerConnected = bridge.isConnected(context.workerId);
      if (!input.data.paused && workerConnected) {
        try {
          await bridge.request(
            context.workerId,
            {
              type: "chat.pause.set",
              chatId: context.chatId,
              paused: false,
            },
            { timeoutMs: null },
          );
        } catch (error) {
          return reply.code(502).send({
            error: `The worker could not resume this chat: ${errorMessage(error)}`,
          });
        }
      }

      if (input.data.paused && workerConnected) {
        try {
          await bridge.request(
            context.workerId,
            {
              type: "chat.pause.set",
              chatId: context.chatId,
              paused: true,
            },
            { timeoutMs: null },
          );
        } catch (error) {
          return reply.code(502).send({
            error: `The worker could not pause this chat at a safe boundary: ${errorMessage(error)}`,
          });
        }
      }

      const updated = await repository.setChatAutomationPaused(
        applicationOwnerId(),
        context.chatId,
        input.data.paused,
      );
      if (!updated) {
        if (workerConnected) {
          await bridge
            .request(
              context.workerId,
              {
                type: "chat.pause.set",
                chatId: context.chatId,
                paused: !input.data.paused,
              },
              { timeoutMs: null },
            )
            .catch(() => undefined);
        }
        return reply.code(404).send({ error: "Chat source not found." });
      }

      if (!input.data.paused) {
        try {
          await resumeChatAutomation(context.chatId);
        } catch (error) {
          await repository.setChatAutomationPaused(
            applicationOwnerId(),
            context.chatId,
            true,
          );
          if (bridge.isConnected(context.workerId)) {
            await bridge
              .request(context.workerId, {
                type: "chat.pause.set",
                chatId: context.chatId,
                paused: true,
              })
              .catch(() => undefined);
          }
          return reply.code(409).send({
            error: `This chat remains paused because its next action could not start: ${errorMessage(error)}`,
          });
        }
      }

      app.log.info(
        {
          event: input.data.paused
            ? "chat.automation.paused"
            : "chat.automation.resumed",
          subsystem: "chat-execution",
          operation: input.data.paused ? "pause" : "resume",
          status: input.data.paused ? "paused" : "active",
          chatId: context.chatId,
          projectId: context.projectId,
          workerId: context.workerId,
        },
        input.data.paused
          ? "Chat automation paused"
          : "Chat automation resumed",
      );

      return reply.send(
        chatPauseStateSchema.parse({ paused: input.data.paused }),
      );
    },
  );

